-- ============================================================
-- Tabla: sesiones_avance_estudiantil
-- Descripción: Registra sesiones de avance individuales que un
--   docente crea para cada estudiante (especialidad, práctica
--   de conjuntos o instrumento complementario).
--   Cada fila es UNA clase / sesión de avance.
-- ============================================================

DROP TABLE IF EXISTS `sesiones_avance_estudiantil`;
CREATE TABLE `sesiones_avance_estudiantil` (
    id INT AUTO_INCREMENT PRIMARY KEY,

    -- Estudiante (inscripción)
    infoestudiantesifas_id INT NOT NULL,

    -- Docente que crea la sesión (planteldocentes, NO planteldocentesmaterias)
    planteldocentes_id INT NOT NULL,

    -- Tipo de asignación: determina cuál FK de infoestudiantesifas se usó
    -- Valores: ESPECIALIDAD | PRACTICA_CONJUNTOS | COMPLEMENTARIO
    tipo_asignacion VARCHAR(30) NOT NULL DEFAULT 'ESPECIALIDAD',

    -- Evaluación a la que pertenece (1=Primera, 2=Segunda, 3=Tercera, 4=Cuarta)
    evaluacion TINYINT NOT NULL DEFAULT 1,

    -- Fecha de la clase
    fecha DATE NOT NULL,

    -- Número correlativo de clase (1, 2, 3…) por estudiante
    numero_clase INT NOT NULL DEFAULT 1,

    -- Contenido de avance (HTML de Quill Editor)
    avance_texto TEXT NULL,

    -- Valoración de 1 a 5 estrellas (NULL = sin calificar)
    estrellas TINYINT NULL,

    -- Sugerencia / mensaje del docente al estudiante
    sugerencia TEXT NULL,

    -- Asistencia: P=presente, A=atraso, F=falta, L=licencia
    asistencia CHAR(1) NULL DEFAULT NULL,

    created_at DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    FOREIGN KEY (infoestudiantesifas_id)
        REFERENCES infoestudiantesifas(id) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY (planteldocentes_id)
        REFERENCES planteldocentes(id) ON UPDATE CASCADE ON DELETE RESTRICT,

    INDEX idx_sesav_info (infoestudiantesifas_id),
    INDEX idx_sesav_docente (planteldocentes_id),
    INDEX idx_sesav_tipo (tipo_asignacion),
    INDEX idx_sesav_eval (evaluacion),
    INDEX idx_sesav_fecha (fecha)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




